<script setup lang="ts">
import { ref } from 'vue';import { Head } from '@inertiajs/vue3';import { locale } from '../../i18n';import SiteHeader from '../../components/website/SiteHeader.vue';import SiteFooter from '../../components/website/SiteFooter.vue';import Icon from '../../components/website/Icon.vue';import type { SiteDocument } from '../../components/website/types';defineProps<{navigation:SiteDocument}>();const tr=(id:string,en:string)=>locale.value==='id'?id:en;
const form=ref({name:'',email:'',phone:'',business_type:'retail',consent:false,marketing_consent:false,website:''}),busy=ref(false),done=ref(false),error=ref('');
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/register',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({...form.value,locale:locale.value}),signal:AbortSignal.timeout(25000)});if(!r.ok)throw new Error(String(r.status));const data=await r.json();if(data.status!=='received')throw new Error();done.value=true;}catch(e){error.value=e instanceof Error&&e.message==='429'?tr('Terlalu banyak permintaan. Silakan coba lagi nanti.','Too many requests. Please try later.'):tr('Pendaftaran belum terkonfirmasi. Periksa isian atau ulangi dengan email yang sama.','Registration is not confirmed. Check your details or retry using the same email.');}finally{busy.value=false;}}
</script>
<template><div class="oneqay-site"><Head :title="tr('Daftarkan bisnis | oneQay','Register your business | oneQay')"/><SiteHeader :navigation="navigation"/><main class="register-wrap wrap"><div class="register-intro"><p class="site-eyebrow"><span></span>{{ tr('LANGKAH PERTAMA ANDA','YOUR FIRST STEP') }}</p><h1>{{ tr('Bisnis Anda.\nRuang tumbuh baru.','Your business.\nA new space to grow.') }}</h1><p>{{ tr('Ceritakan sedikit tentang bisnis Anda. Setelah permohonan disetujui, Anda menerima undangan untuk membuat akun admin bisnis.','Tell us a little about your business. After approval, you receive an invitation to create your business admin account.') }}</p><ol><li><b>01</b><div><strong>{{ tr('Daftarkan bisnis','Register your business') }}</strong><p>{{ tr('Gunakan email aktif yang Anda kuasai.','Use an active email that you control.') }}</p></div></li><li><b>02</b><div><strong>{{ tr('Tinjau & aktivasi','Review & activation') }}</strong><p>{{ tr('Undangan dikirim setelah persetujuan.','An invitation follows approval.') }}</p></div></li><li><b>03</b><div><strong>{{ tr('Mulai operasional','Start operating') }}</strong><p>{{ tr('Siapkan produk, tim, dan hak akses.','Set up products, your team and access.') }}</p></div></li></ol></div><section class="registration-card"><div v-if="done" class="registration-success" role="status"><span class="success-check"><Icon name="check"/></span><h2>{{ tr('Permohonan diterima.','Request received.') }}</h2><p>{{ tr('Jika email belum terdaftar, permohonan masuk ke peninjauan pemilik platform. Aktivasi tidak berlangsung otomatis. Tunggu undangan melalui email, lalu buat kata sandi Anda sendiri.','If this email is not registered, your request is awaiting platform-owner review. Activation is not automatic. Wait for an email invitation, then set your own password.') }}</p><a class="site-btn" href="/business-login">{{ tr('Ke halaman masuk','Go to login') }}<Icon name="log-in"/></a><a class="site-text-link" href="/">{{ tr('Kembali ke beranda','Back to home') }}</a></div><form v-else @submit.prevent="submit"><h2>{{ tr('Mari mulai.','Let’s get started.') }}</h2><p>{{ tr('Lengkapi informasi bisnis Anda.','Enter your business information.') }}</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><fieldset :disabled="busy"><label>{{ tr('Nama bisnis','Business name') }}<input v-model="form.name" required maxlength="160" autocomplete="organization"/></label><label>{{ tr('Email pemilik bisnis','Business owner email') }}<input v-model="form.email" type="email" required maxlength="254" autocomplete="email" placeholder="nama@bisnis.com"/></label><label>{{ tr('Nomor kontak','Contact number') }}<input v-model="form.phone" type="tel" inputmode="tel" required pattern="\+?[0-9 ]{7,23}" maxlength="24" autocomplete="tel" placeholder="+62 812 3456 7890"/></label><label>{{ tr('Jenis bisnis','Business type') }}<select v-model="form.business_type"><option value="retail">{{ tr('Toko ritel','Retail store') }}</option><option value="food">{{ tr('Makanan & minuman','Food & beverage') }}</option><option value="services">{{ tr('Jasa','Services') }}</option><option value="other">{{ tr('Lainnya','Other') }}</option></select></label><label class="honey" aria-hidden="true">Website<input v-model="form.website" tabindex="-1" autocomplete="off"/></label><label class="consent"><input v-model="form.consent" type="checkbox" required/><span>{{ tr('Saya menyetujui','I agree to the') }} <a href="/pages/terms" target="_blank" rel="noopener">{{ tr('ketentuan pendaftaran','registration terms') }}</a> {{ tr('dan','and') }} <a href="/pages/privacy" target="_blank" rel="noopener">{{ tr('informasi privasi','privacy information') }}</a>.</span></label><label class="consent"><input v-model="form.marketing_consent" type="checkbox"/><span>{{ tr('Saya ingin menerima informasi produk dan penawaran oneQay melalui email (opsional).','I would like product news and offers from oneQay by email (optional).') }}</span></label><button class="site-btn" type="submit">{{ busy?tr('Mengirim…','Submitting…'):tr('Ajukan pendaftaran','Submit registration') }}<Icon name="arrow-up-right"/></button></fieldset><p class="form-footnote">{{ tr('Sudah punya akun?','Already have an account?') }} <a href="/business-login">{{ tr('Masuk di sini','Log in here') }}</a></p></form></section></main><SiteFooter :navigation="navigation"/></div></template>
